mapper.select:
SELECT a.id, a.login_account AS loginAccount, a.username, a.email, a.mobile, a.status, a.created_time AS createdTime, a.updated_time AS updatedTime FROM admin a
( a.username LIKE CONCAT('%', #{keyword}, '%') OR a.login_account = #{keyword} OR a.email LIKE CONCAT(#{keyword}, '%') OR a.mobile LIKE CONCAT(#{keyword}, '%') )
AND a.status = #{status}
AND a.deleted = #{deleted}
ORDER BY a.created_time DESC
